-- ===================================================================
-- 06_indexes.sql
--
-- All indexes. Must precede any data load: the seed scripts' ON CONFLICT
-- targets rely on the partial unique indexes declared here.
--
-- Generated by the db_scripts consolidation. Fresh-install only:
-- there is no in-place upgrade path, no ALTER-after-the-fact section,
-- and no _migrations/ folder. Schema changes are made in the
-- CREATE statement itself and the database is rebuilt.
-- ===================================================================

BEGIN;

-- ── geo.* (tenant-scoped, 02_tables_core.sql) ─────────────────────────────
-- Name uniqueness has to be a PAIR of partial indexes per rule, not one
-- constraint: NULLs are distinct in a unique index, so a single
-- UNIQUE (tenant_id, name) would let the platform templates
-- (tenant_id IS NULL) duplicate freely. Same shape as iam.user_roles above.
-- (PG 15's UNIQUE NULLS NOT DISTINCT would collapse each pair, but the
-- platform targets PG 14+.)
CREATE UNIQUE INDEX IF NOT EXISTS uix_geo_countries_template_name
  ON geo.countries (name)                WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uix_geo_countries_template_iso
  ON geo.countries (iso_code)            WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uix_geo_countries_tenant_name
  ON geo.countries (tenant_id, name)     WHERE tenant_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uix_geo_countries_tenant_iso
  ON geo.countries (tenant_id, iso_code) WHERE tenant_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uix_geo_states_template_name
  ON geo.states (country_id, name)            WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uix_geo_states_tenant_name
  ON geo.states (tenant_id, country_id, name) WHERE tenant_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uix_geo_cities_template_name
  ON geo.cities (state_id, name)            WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uix_geo_cities_tenant_name
  ON geo.cities (tenant_id, state_id, name) WHERE tenant_id IS NOT NULL;

-- Cascade lookups: every dropdown query filters (tenant_id, parent_id) and
-- most add is_active. The FK columns had no index of their own before.
CREATE INDEX IF NOT EXISTS idx_geo_states_tenant_country
  ON geo.states (tenant_id, country_id) WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_geo_cities_tenant_state
  ON geo.cities (tenant_id, state_id)   WHERE is_active;

-- Reverse lookups from a place to the branches in it (public presence API).
CREATE INDEX IF NOT EXISTS idx_organizations_city    ON entity.organizations (city_id)    WHERE city_id    IS NOT NULL AND NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_organizations_state   ON entity.organizations (state_id)   WHERE state_id   IS NOT NULL AND NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_organizations_country ON entity.organizations (country_id) WHERE country_id IS NOT NULL AND NOT is_deleted;

-- One department name per (tenant, org-or-tenantwide); the zero-UUID collapses a
-- NULL org_id so tenant-wide names collide correctly.
CREATE UNIQUE INDEX IF NOT EXISTS uix_iam_departments_scope_name
  ON iam.departments (tenant_id, COALESCE(org_id, '00000000-0000-0000-0000-000000000000'::uuid), name)
  WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_iam_departments_tenant ON iam.departments (tenant_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_iam_departments_org    ON iam.departments (org_id)    WHERE org_id IS NOT NULL AND NOT is_deleted;
-- NAME uniqueness: anchors unique globally by name; tenant roles unique per tenant.
CREATE UNIQUE INDEX IF NOT EXISTS uix_user_roles_global_name
  ON iam.user_roles (name) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uix_user_roles_tenant_name
  ON iam.user_roles (tenant_id, name) WHERE tenant_id IS NOT NULL;
-- RANK uniqueness (unambiguous hierarchy): anchors distinct among the global set;
-- tenant roles distinct within a (tenant, department) scope.
CREATE UNIQUE INDEX IF NOT EXISTS uix_user_roles_global_rank
  ON iam.user_roles (rank) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uix_user_roles_tenant_dept_rank
  ON iam.user_roles (tenant_id, department_id, rank) WHERE tenant_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_iam_capabilities_parent ON iam.capabilities (parent_key) WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_iam_capabilities_kind   ON iam.capabilities (kind)       WHERE is_active;
-- One grant row per (role, capability) at each level. Partial indexes because a
-- plain UNIQUE would let NULL tenant_id duplicate freely.
CREATE UNIQUE INDEX IF NOT EXISTS uix_role_capabilities_default
  ON iam.role_capabilities (role_id, capability_id) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uix_role_capabilities_tenant
  ON iam.role_capabilities (tenant_id, role_id, capability_id) WHERE tenant_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_role_capabilities_tenant
  ON iam.role_capabilities (tenant_id) WHERE tenant_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_user_org_mapping_user_active
  ON iam.user_org_mapping (user_id) WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_user_org_mapping_org_active
  ON iam.user_org_mapping (org_id)  WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_user_org_mapping_role
  ON iam.user_org_mapping (role_id);

CREATE INDEX IF NOT EXISTS idx_marketing_leads_is_active    ON lms.marketing_leads (org_id, is_active) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_marketing_leads_superseded_by ON lms.marketing_leads (superseded_by)    WHERE superseded_by IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_lead_links_source_lead  ON lms.lead_links (source_lead_id);
CREATE INDEX IF NOT EXISTS idx_lead_links_dest_lead    ON lms.lead_links (dest_lead_id) WHERE dest_lead_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_lead_links_source_org   ON lms.lead_links (source_org_id);
CREATE INDEX IF NOT EXISTS idx_lead_links_dest_org     ON lms.lead_links (dest_org_id);

CREATE INDEX IF NOT EXISTS idx_api_clients_tenant   ON iam.api_clients (tenant_id);
CREATE INDEX IF NOT EXISTS idx_api_clients_key_hash ON iam.api_clients (key_hash) WHERE is_active;

CREATE INDEX IF NOT EXISTS idx_api_client_orgs_org ON iam.api_client_orgs (org_id);

-- ── PASSWORD-SPRAY DETECTION ──────────────────────────────────────
-- Detects password SPRAYING, which the per-account lockout on iam.users
-- (failed_login_attempts / locked_until) deliberately does not catch.
--
-- The two attacks have opposite shapes:
--   brute force -> MANY failures against ONE account  (lockout fires)
--   spraying    -> ONE or TWO tries against MANY accounts, so every
--                  account's counter stays at 1-2, no lockout ever fires,
--                  and nothing looks wrong per-account.
--
-- Spraying is only visible in aggregate, so this reads the login_failure
-- rows identity-service already writes above. No new write path and no
-- hot-path cost -- it is a read-side query over data that already exists.
--
-- Targets are keyed on the submitted login identifier, NOT `performed_by`:
-- the latter is NULL when the identifier does not resolve to a real user,
-- which is exactly what a spray against guessed addresses looks like.
--
-- COALESCE over 'identifier' then 'email': login accepts an email OR a mobile
-- number, so identity-service now writes the generic `identifier` key. Rows
-- written before login-by-mobile carry `email` instead, and they must keep
-- counting -- dropping them would blind the detector across the upgrade and
-- silently reset every in-flight spray window.

-- Partial index: login failures are a small slice of the table.
CREATE INDEX IF NOT EXISTS idx_activities_login_failure
  ON audit.activities (created_at DESC, org_id)
  WHERE action_type IN ('login_failure', 'account_locked');

CREATE INDEX IF NOT EXISTS idx_lead_status_log_lead_changed
  ON lms.lead_status_log (org_id, lead_id, changed_at DESC);
CREATE INDEX IF NOT EXISTS idx_lead_status_log_org_changed
  ON lms.lead_status_log (org_id, changed_at DESC);
CREATE INDEX IF NOT EXISTS idx_lead_status_log_changed_by
  ON lms.lead_status_log (org_id, changed_by_id, changed_at DESC);

CREATE INDEX IF NOT EXISTS idx_marketing_leads_history_lead_changed
  ON audit.marketing_leads_history (lead_id, changed_at DESC);

CREATE INDEX IF NOT EXISTS idx_audit_log_table_record
  ON audit.audit_log (table_name, record_id, changed_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_log_org_table
  ON audit.audit_log (org_id, table_name, changed_at DESC)
  WHERE org_id IS NOT NULL;

-- NULLS NOT DISTINCT (PG15+) so the global row and a tenant's override of the
-- same name collide only when they target the same audience. Without it every
-- NULL tenant_id would be treated as distinct and duplicate globals would slip in.
CREATE UNIQUE INDEX IF NOT EXISTS uix_message_templates_audience_name
  ON comms.message_templates (tenant_id, org_id, module, channel, name)
  NULLS NOT DISTINCT
  WHERE NOT is_deleted;

CREATE INDEX IF NOT EXISTS idx_message_templates_lookup
  ON comms.message_templates (module, channel, sort_order)
  WHERE is_active AND NOT is_deleted;

-- ===================================================================
-- INDEXES
-- ===================================================================

-- lms.marketing_leads
CREATE INDEX IF NOT EXISTS idx_marketing_leads_org_stage_created
  ON lms.marketing_leads (org_id, stage_id, created_at DESC) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_marketing_leads_org_created
  ON lms.marketing_leads (org_id, created_at DESC) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_marketing_leads_org_assigned_user
  ON lms.marketing_leads (org_id, assigned_user_id, created_at DESC) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_marketing_leads_org_campaign
  ON lms.marketing_leads (org_id, campaign_id) WHERE campaign_id IS NOT NULL AND NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_marketing_leads_org_outcome
  ON lms.marketing_leads (org_id, outcome_id) WHERE outcome_id IS NOT NULL AND NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_marketing_leads_org_phone
  ON lms.marketing_leads (org_id, phone) WHERE phone IS NOT NULL AND NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_marketing_leads_org_email
  ON lms.marketing_leads (org_id, email) WHERE email IS NOT NULL AND NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_marketing_leads_fullname_trgm
  ON lms.marketing_leads USING GIN (full_name gin_trgm_ops) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_marketing_leads_webhook_gin
  ON lms.marketing_leads USING GIN (raw_webhook_data jsonb_path_ops);
CREATE INDEX IF NOT EXISTS idx_marketing_leads_metadata_gin
  ON lms.marketing_leads USING GIN (metadata jsonb_path_ops);
CREATE INDEX IF NOT EXISTS idx_marketing_leads_tags_gin
  ON lms.marketing_leads USING GIN (tags);

-- lms.lead_interactions
CREATE INDEX IF NOT EXISTS idx_lead_interactions_org_lead_occurred
  ON lms.lead_interactions (org_id, lead_id, occurred_at DESC) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_lead_interactions_lead_id
  ON lms.lead_interactions (lead_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_lead_interactions_lead_id_full
  ON lms.lead_interactions (lead_id);

-- lms.lead_follow_ups
CREATE INDEX IF NOT EXISTS idx_lead_follow_ups_org_user_scheduled
  ON lms.lead_follow_ups (org_id, assigned_user_id, scheduled_at ASC, status_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_lead_follow_ups_lead_id
  ON lms.lead_follow_ups (lead_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_lead_follow_ups_lead_id_full
  ON lms.lead_follow_ups (lead_id);

-- lms.lead_assignment_log
CREATE INDEX IF NOT EXISTS idx_lead_assignment_log_lead
  ON lms.lead_assignment_log (org_id, lead_id, assigned_at DESC);
CREATE INDEX IF NOT EXISTS idx_lead_assignment_log_assigned_by
  ON lms.lead_assignment_log (org_id, assigned_by_id, assigned_at DESC);
CREATE INDEX IF NOT EXISTS idx_lead_assignment_log_assigned_to
  ON lms.lead_assignment_log (org_id, assigned_to_id, assigned_at DESC);
CREATE INDEX IF NOT EXISTS idx_lead_assignment_log_lead_id_full
  ON lms.lead_assignment_log (lead_id);

-- marketing.ad_campaigns
CREATE INDEX IF NOT EXISTS idx_ad_campaigns_org_platform
  ON marketing.ad_campaigns (org_id, platform_id) WHERE NOT is_deleted;
CREATE UNIQUE INDEX IF NOT EXISTS uix_ad_campaigns_org_meta_campaign_id
  ON marketing.ad_campaigns (org_id, meta_campaign_id)
  WHERE meta_campaign_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_ad_campaigns_meta_campaign_id
  ON marketing.ad_campaigns (meta_campaign_id)
  WHERE meta_campaign_id IS NOT NULL;

-- entity.organizations
CREATE INDEX IF NOT EXISTS idx_organizations_tenant_id
  ON entity.organizations (tenant_id) WHERE NOT is_deleted;

-- iam.users
CREATE INDEX IF NOT EXISTS idx_users_org_role
  ON iam.users (org_id, role_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_users_org_email
  ON iam.users (org_id, email) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_users_email_trgm
  ON iam.users USING GIN (email gin_trgm_ops) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_users_manager_id
  ON iam.users (org_id, manager_id) WHERE manager_id IS NOT NULL AND NOT is_deleted;

-- Mobile is a login credential (see login-by-mobile in identity-service), so it
-- must resolve to exactly one live account. Partial, because mobile stays
-- optional: users without one simply keep logging in by email, and soft-deleted
-- rows must not hold a number hostage against re-use.
--
-- Uniqueness is only meaningful if every writer stores the SAME spelling of a
-- number, so all writes go through normalizeMobile() in @platform/validation
-- (packages/platform-validation/src/phone.ts) and land as E.164 '+919876543210'.
-- Keep the two in sync.
CREATE UNIQUE INDEX IF NOT EXISTS uix_users_mobile
  ON iam.users (mobile) WHERE mobile IS NOT NULL AND NOT is_deleted;

CREATE UNIQUE INDEX IF NOT EXISTS idx_token_blocklist_jti
  ON iam.token_blocklist (jti) WHERE jti IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_token_blocklist_user
  ON iam.token_blocklist (user_id, revoked_at) WHERE user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_token_blocklist_org
  ON iam.token_blocklist (org_id, revoked_at) WHERE org_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_token_blocklist_tenant
  ON iam.token_blocklist (tenant_id, revoked_at) WHERE tenant_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_token_blocklist_expires
  ON iam.token_blocklist (expires_at);

-- Prevent duplicate active leads per org on phone and email.
-- Partial indexes: enforced only for active, non-deleted rows.
-- is_active = true ensures superseded rows can share the same phone/email.
CREATE UNIQUE INDEX IF NOT EXISTS uix_marketing_leads_org_phone
  ON lms.marketing_leads (org_id, phone)
  WHERE phone IS NOT NULL AND NOT is_deleted AND is_active = true;

CREATE UNIQUE INDEX IF NOT EXISTS uix_marketing_leads_org_email
  ON lms.marketing_leads (org_id, email)
  WHERE email IS NOT NULL AND NOT is_deleted AND is_active = true;

-- At most one shared-app row (tenant_id IS NULL) may exist at a time.
-- uq_meta_tenant_config_tenant above already allows multiple NULLs
-- (Postgres treats NULLs as distinct in a plain UNIQUE constraint), so it
-- does not enforce this on its own.
CREATE UNIQUE INDEX IF NOT EXISTS uix_meta_tenant_config_one_shared
  ON ext.meta_tenant_config ((true))
  WHERE tenant_id IS NULL;

CREATE INDEX IF NOT EXISTS idx_meta_page_form_org_map_org    ON ext.meta_page_form_org_map (org_id);
CREATE INDEX IF NOT EXISTS idx_meta_page_form_org_map_tenant ON ext.meta_page_form_org_map (tenant_id);
CREATE INDEX IF NOT EXISTS idx_meta_page_form_org_map_page   ON ext.meta_page_form_org_map (page_id);

CREATE INDEX IF NOT EXISTS idx_meta_forms_tenant ON ext.meta_forms (tenant_id);
CREATE INDEX IF NOT EXISTS idx_meta_forms_page   ON ext.meta_forms (page_id);

CREATE INDEX IF NOT EXISTS idx_meta_leads_org          ON ext.meta_leads (org_id);
CREATE INDEX IF NOT EXISTS idx_meta_leads_form         ON ext.meta_leads (form_id);
CREATE INDEX IF NOT EXISTS idx_meta_leads_campaign     ON ext.meta_leads (campaign_id) WHERE campaign_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_meta_leads_mktg_lead    ON ext.meta_leads (marketing_lead_id) WHERE marketing_lead_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_meta_leads_created      ON ext.meta_leads (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_capi_logs_org           ON ext.meta_capi_outbound_logs (org_id);
CREATE INDEX IF NOT EXISTS idx_capi_logs_lead          ON ext.meta_capi_outbound_logs (marketing_lead_id);
CREATE INDEX IF NOT EXISTS idx_capi_logs_sent          ON ext.meta_capi_outbound_logs (sent_at DESC);

CREATE UNIQUE INDEX IF NOT EXISTS uix_capi_logs_lead_event_success
  ON ext.meta_capi_outbound_logs (marketing_lead_id, event_name)
  WHERE delivery_status = 'SUCCESS';

CREATE INDEX IF NOT EXISTS idx_lead_stage_capi_event_map_event_type
  ON ext.lead_stage_capi_event_map (capi_event_type_id);
-- Tenant-scoped as of 1.25.0; every RLS-filtered read starts from tenant_id.
CREATE INDEX IF NOT EXISTS idx_lead_stage_capi_event_map_tenant
  ON ext.lead_stage_capi_event_map (tenant_id);

CREATE INDEX IF NOT EXISTS idx_meta_lead_addresses_org ON ext.meta_lead_addresses (org_id);

CREATE INDEX IF NOT EXISTS idx_meta_lead_professional_org ON ext.meta_lead_professional (org_id);

CREATE INDEX IF NOT EXISTS idx_meta_lead_demographics_org ON ext.meta_lead_demographics (org_id);

CREATE INDEX IF NOT EXISTS idx_tenant_modules_tenant
  ON entity.tenant_modules (tenant_id) WHERE is_active;

CREATE INDEX IF NOT EXISTS idx_designations_org
  ON hr.designations (org_id) WHERE NOT is_deleted;
CREATE UNIQUE INDEX IF NOT EXISTS uix_designations_org_name
  ON hr.designations (org_id, name) WHERE NOT is_deleted;

CREATE INDEX IF NOT EXISTS idx_employee_profiles_org
  ON hr.employee_profiles (org_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_employee_profiles_tenant
  ON hr.employee_profiles (tenant_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_employee_profiles_department
  ON hr.employee_profiles (department_id) WHERE department_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_employee_profiles_designation
  ON hr.employee_profiles (designation_id) WHERE designation_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_employee_profiles_employment_type
  ON hr.employee_profiles (employment_type_id) WHERE employment_type_id IS NOT NULL;

-- employee_code unique per tenant, among non-deleted rows that have a code.
CREATE UNIQUE INDEX IF NOT EXISTS uix_employee_profiles_tenant_code
  ON hr.employee_profiles (tenant_id, employee_code)
  WHERE employee_code IS NOT NULL AND NOT is_deleted;

CREATE INDEX IF NOT EXISTS idx_holiday_calendars_org
  ON hr.holiday_calendars (org_id) WHERE NOT is_deleted;
CREATE UNIQUE INDEX IF NOT EXISTS uix_holiday_calendars_org_name_year
  ON hr.holiday_calendars (org_id, name, year) WHERE NOT is_deleted;

CREATE INDEX IF NOT EXISTS idx_holidays_calendar
  ON hr.holidays (calendar_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_holidays_org_date
  ON hr.holidays (org_id, holiday_date) WHERE NOT is_deleted;

CREATE INDEX IF NOT EXISTS idx_leave_policies_tenant
  ON hr.leave_policies (tenant_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_leave_policies_org
  ON hr.leave_policies (org_id) WHERE org_id IS NOT NULL AND NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_leave_policies_leave_type
  ON hr.leave_policies (leave_type_id) WHERE NOT is_deleted;

-- One effective-dated policy row per (tenant, org|tenant-wide, leave_type,
-- applicable_from). COALESCE folds the tenant-wide NULL org into the zero-uuid
-- so a tenant default and an org override never collide.
CREATE UNIQUE INDEX IF NOT EXISTS uix_leave_policies_scope_type_from
  ON hr.leave_policies (
    tenant_id,
    COALESCE(org_id, '00000000-0000-0000-0000-000000000000'::uuid),
    leave_type_id,
    applicable_from
