CREATE INDEX IF NOT EXISTS idx_attendance_events_org
  ON hr.attendance_events (org_id);

CREATE INDEX IF NOT EXISTS idx_attendance_days_org_date
  ON hr.attendance_days (org_id, work_date);
CREATE INDEX IF NOT EXISTS idx_attendance_days_user_date
  ON hr.attendance_days (user_id, work_date);
CREATE INDEX IF NOT EXISTS idx_attendance_days_leave_request
  ON hr.attendance_days (leave_request_id) WHERE leave_request_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_attendance_regularizations_user
  ON hr.attendance_regularizations (user_id, work_date DESC) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_attendance_regularizations_org_status
  ON hr.attendance_regularizations (org_id, status) WHERE NOT is_deleted;
-- One open (pending) regularization per user per date.
CREATE UNIQUE INDEX IF NOT EXISTS uix_attendance_regularizations_open
  ON hr.attendance_regularizations (user_id, work_date)
  WHERE status = 'pending' AND NOT is_deleted;

CREATE INDEX IF NOT EXISTS idx_reporting_lines_org_user
  ON hr.reporting_lines (org_id, user_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_reporting_lines_org_manager
  ON hr.reporting_lines (org_id, manager_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_reporting_lines_tenant
  ON hr.reporting_lines (tenant_id) WHERE NOT is_deleted;

CREATE INDEX IF NOT EXISTS idx_task_lists_org
  ON task.task_lists (org_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_task_lists_owner
  ON task.task_lists (owner_id) WHERE NOT is_deleted;

CREATE INDEX IF NOT EXISTS idx_tasks_org_assignee_status
  ON task.tasks (org_id, assignee_id, status_id) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_tasks_org_due
  ON task.tasks (org_id, due_at) WHERE completed_at IS NULL AND NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_tasks_related_entity
  ON task.tasks (related_entity_type, related_entity_id) WHERE related_entity_type IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_tasks_list
  ON task.tasks (list_id) WHERE list_id IS NOT NULL AND NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_tasks_created_by
  ON task.tasks (org_id, created_by) WHERE NOT is_deleted;
CREATE INDEX IF NOT EXISTS idx_tasks_parent
  ON task.tasks (parent_task_id) WHERE parent_task_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_task_status_log_task
  ON task.task_status_log (org_id, task_id, changed_at DESC);

CREATE INDEX IF NOT EXISTS idx_task_comments_task
  ON task.task_comments (org_id, task_id, created_at);

CREATE INDEX IF NOT EXISTS idx_lms_member_roles_org_active
  ON lms.member_roles (org_id)    WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_lms_member_roles_tenant_active
  ON lms.member_roles (tenant_id) WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_lms_member_roles_role
  ON lms.member_roles (role_id);

CREATE INDEX IF NOT EXISTS idx_hr_member_roles_org_active
  ON hr.member_roles (org_id)    WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_hr_member_roles_tenant_active
  ON hr.member_roles (tenant_id) WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_hr_member_roles_role
  ON hr.member_roles (role_id);

CREATE INDEX IF NOT EXISTS idx_task_member_roles_org_active
  ON task.member_roles (org_id)    WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_task_member_roles_tenant_active
  ON task.member_roles (tenant_id) WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_task_member_roles_role
  ON task.member_roles (role_id);
CREATE INDEX IF NOT EXISTS idx_catalog_defaults_key_version
  ON entity.catalog_defaults (catalog_key, version);
CREATE INDEX IF NOT EXISTS idx_tenant_catalog_versions_tenant
  ON entity.tenant_catalog_versions (tenant_id);
-- ===================================================================
-- Template-row uniqueness for the per-tenant LMS catalogs
--
-- The (tenant_id, name) constraint on these tables does not constrain the
-- global template rows, since NULL tenant_id values are distinct. Without
-- these, re-running reference_data/ would duplicate every template.
-- ===================================================================
CREATE UNIQUE INDEX IF NOT EXISTS uix_lead_stage_global_name
  ON lms.lead_stage (name) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uix_interaction_types_global_name
  ON lms.interaction_types (name) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uix_follow_up_statuses_global_name
  ON lms.follow_up_statuses (name) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uix_lead_sources_global_name
  ON lms.lead_sources (name) WHERE tenant_id IS NULL;
-- The two marketing catalogs belong in this set too. They were missing it
-- because until 1.26.0 they carried a plain global UNIQUE (name), which both
-- served as the template guard and made per-tenant cloning impossible.
CREATE UNIQUE INDEX IF NOT EXISTS uix_marketing_platforms_global_name
  ON marketing.marketing_platforms (name) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uix_campaign_statuses_global_name
  ON marketing.campaign_statuses (name) WHERE tenant_id IS NULL;

COMMIT;
